"""KinDER sensor controller and exact action replay.
All scene measurements come from RGB-D; robot geometry comes from spec().
Invoke with --replay to replay the saved action sequence on a fresh service.
"""
import json, argparse
from pathlib import Path
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from rcb_client import Robot
OUT=Path('/app/output')
r=Robot()
spec=r.spec()
P=np.array(spec['arm']['position_m']); AX=np.array(spec['arm']['axis']); EE=np.array(spec['arm']['end_effector']['position_m'])

def fk(q,base=None):
    R=np.eye(3); t=np.zeros(3)
    for p,a,angle in zip(P,AX,q):
        Ri=Rotation.from_rotvec(a*angle).as_matrix()
        t=t+R@(p-Ri@p); R=R@Ri
    if base is not None:
        Rb=Rotation.from_euler('z',base[2]).as_matrix()
        t=Rb@t+np.r_[base[:2],0]; R=Rb@R
    return R,t

def pose(q,base=None):
    R,t=fk(q,base); return R@EE+t,R

def observe(tag='obs'):
    res=r.get_obs(include_depth=True,video='none'); save(res,tag); return res

def save(res,tag):
    res.save(OUT/tag)
    (OUT/'current.json').write_text(json.dumps(res.meta))

def state():
    return np.array(r.get_obs(cameras=[],video='none').meta['proprio']['now'])

def submit(a,tag='latest'):
    a=np.asarray(a).reshape(-1,11)
    with (OUT/'actions.jsonl').open('a') as f:
        for row in a: f.write(json.dumps(row.tolist())+'\n')
    res=r.submit('delta',a,include_depth=True,video='none'); save(res,tag)
    if res.done: print('EPISODE ENDED',res.meta)
    return res

def ik(pos,rot,q,base=None):
    lo=np.array([-100,-2.239,-100,-2.569,-100,-2.089,-100]); hi=np.array([100,2.239,100,2.569,100,2.089,100])
    def fun(x):
        p,R=pose(x,base)
        return np.r_[(p-np.array(pos))*5,Rotation.from_matrix(rot@R.T).as_rotvec(),(x-q)*.001]
    sol=least_squares(fun,np.clip(q,lo+1e-6,hi-1e-6),bounds=(lo,hi),max_nfev=250,ftol=1e-10,xtol=1e-10,gtol=1e-10)
    return sol.x,np.linalg.norm(fun(sol.x)[:6])

def move(q=None,base=None,grip=0,max_steps=80,tol=.006,tag='latest'):
    for k in range(max_steps):
        s=state(); a=np.zeros(11); a[-1]=grip
        if q is not None:a[3:10]=np.clip(np.array(q)-s[6:13],-.095,.095)
        if base is not None:
            e=np.array(base)-s[:3]; a[:2]=e[:2]*min(1,.085/(np.linalg.norm(e[:2])+1e-12)); a[2]=np.clip(e[2],-.095,.095)
        err=max(np.max(np.abs(a[:3])),np.max(np.abs(a[3:10])))
        if err<tol and k>0:break
        res=submit(a,tag)
        if res.done:break
    s=state(); print('move',k,'steps',r.status()['control_steps'],'base',s[:3].round(4),'q',s[6:13].round(4),'ee',pose(s[6:13],s[:3])[0].round(4),'grip',s[-2])
    return s

def cart(pos,rot,base=None,grip=0,**kw):
    s=state(); b=s[:3] if base is None else np.array(base)
    q,err=ik(pos,rot,s[6:13],b); print('IK',err,'q',q.round(3))
    if err>.025: raise RuntimeError('IK did not converge')
    return move(q,b,grip,**kw)

def cloud(res,cam='robot_wrist'):
    s=np.array(res.meta['proprio']['now']); R,t=fk(s[6:13],s[:3]); cp=spec['cameras'][cam]['pose']
    pos=R@cp['position_m']+t; right=R@cp['right']; up=R@cp['up']; forward=R@cp['forward']
    d=res.depth[cam][-1].astype(float); h,w=d.shape; f=h/2/np.tan(np.deg2rad(spec['cameras'][cam]['fovy_deg']/2))
    v,u=np.mgrid[:h,:w]
    xyz=pos+d[:,:,None]*(forward+((u-(w-1)/2)/f)[:,:,None]*right-((v-(h-1)/2)/f)[:,:,None]*up)
    return xyz

if __name__=='__main__':
    parser=argparse.ArgumentParser(); parser.add_argument('--replay',action='store_true'); args=parser.parse_args()
    if args.replay:
        A=np.array([json.loads(x) for x in (OUT/'actions.jsonl').read_text().splitlines()])
        for i in range(0,len(A),100):
            res=r.submit('delta',A[i:i+100],video='none')
            if res.done:break
        print(r.status())
    else:
        (OUT/'spec.json').write_text(json.dumps(spec,indent=2)); res=observe(); print(res.meta)
